function decorateLunarDates(){if(!document.querySelectorAll)return;for(const [selector,key] of [['[data-date]','date'],['[data-finance-day]','financeDay'],['[data-habit-day]','habitDay'],['.period-calendar [data-period-day]','periodDay'],['[data-review-date]','reviewDate']]){document.querySelectorAll(selector).forEach(el=>{if(el.classList.contains('quiet')||!/^\d{4}-/.test(el.dataset[key]))return;const date=el.dataset[key],text=lunarDate(date);if(!text||el.querySelector('.lunar-date'))return;const small=document.createElement('small');small.className='lunar-date';small.textContent=text;el.append(small);el.title=date+' · 农历'+text})}document.querySelectorAll('input[type="date"]').forEach(input=>{let hint=input.nextElementSibling;if(!hint?.classList.contains('lunar-input')){hint=document.createElement('small');hint.className='lunar-input';input.insertAdjacentElement('afterend',hint)}const text=lunarDate(input.value);hint.textContent=text?'农历 '+text:''});const pill=document.querySelector('.date-pill');if(pill&&!pill.querySelector('.lunar-date')){const small=document.createElement('small');small.className='lunar-date';small.textContent='农历 '+lunarDate(today);pill.append(small)}decorateHolidays()}
