function taskScheduleName(t){return scheduleChoices().find(([key])=>key===t.scheduleLinkId)?.[1].title||t.scheduleLinkName||''}
function scheduleTaskPicker(t){const choices=scheduleChoices();return '<label for="f-scheduleLinkId">关联固定安排（可选）</label><select id="f-scheduleLinkId" name="scheduleLinkId"><option value="">不关联</option>'+choices.map(([key,r])=>`<option value="${esc(key)}" ${key===t.scheduleLinkId?'selected':''}>${esc(r.title)}</option>`).join('')+(t.scheduleLinkId&&!choices.some(([key])=>key===t.scheduleLinkId)?`<option value="${esc(t.scheduleLinkId)}" selected>${esc(taskScheduleName(t))}（安排已移除）</option>`:'')+'</select><p class="muted">例如将作业关联到课程。任务日期、完成状态和计时独立，可随时解除关联。</p>'}
function showScheduleTasks(key){formType='scheduleTasks';const r=scheduleChoices().find(([k])=>k===key)?.[1],tasks=state.tasks.filter(t=>t.scheduleLinkId===key).sort((a,b)=>Number(!!a.done)-Number(!!b.done)||a.date.localeCompare(b.date));$('#dialog-title').textContent=(r?.title||'固定安排')+' · 相关任务';$('#form button[type="submit"]').hidden=true;$('#fields').innerHTML=(tasks.length?tasks.map(t=>`<div class="record-row"><div class="grow"><h3>${esc(t.title)}</h3><p>${esc(t.date)} · ${t.done?'已完成':'待完成'} · 已专注 ${focusTotalText(focusElapsed(t))}</p></div><button type="button" data-edit-task="${esc(t.id)}">编辑</button></div>`).join(''):'<p class="muted">还没有相关任务。</p>')+(r?`<button type="button" data-new-linked-task="${esc(key)}">＋ 添加相关任务</button>`:'');$('#dialog').showModal()}
document.addEventListener('click',e=>{const view=e.target.closest('[data-schedule-tasks]'),add=e.target.closest('[data-new-linked-task]');if(view){showScheduleTasks(view.dataset.scheduleTasks)}if(add){$('#dialog').close();openForm('task',{scheduleLinkId:add.dataset.newLinkedTask,date:selectedDate})}});
function taskRows(arr){return arr.length?[...arr].sort((a,b)=>Number(!!a.done)-Number(!!b.done)).map(t=>`<div class="task ${t.done?'done':''}"><button class="quiet task-star ${t.priority?'is-priority':''}" data-priority-task="${t.id}" aria-pressed="${!!t.priority}" aria-label="${t.priority?'取消重点':'设为重点'} ${esc(t.title)}">${t.priority?'★':'☆'}</button><button class="check ${t.done?'done':''}" data-task="${t.id}" aria-label="${t.done?'取消完成':'完成'} ${esc(t.title)}">${t.done?'✓':''}</button><div class="task-content"><div class="task-title">${esc(t.title)}</div><div class="task-meta"><span class="tag ${t.group==='课程与学习'?'purple':['生活事务','运动健康'].includes(t.group)?'green':''}">${esc(t.group)}</span><span>预计 ${t.duration} 分钟</span><span>已专注 <span data-focus-total="${t.id}">${focusTotalText(focusElapsed(t))}</span></span>${t.time?`<span>${t.time}</span>`:''}</div>${t.scheduleLinkId?`<button class="quiet task-course-link" data-schedule-tasks="${esc(t.scheduleLinkId)}">关联：${esc(taskScheduleName(t))}</button>`:''}${descriptionView(t)}</div>${focusControls(t)}<button class="quiet" data-edit-task="${t.id}" aria-label="编辑任务">···</button></div>`).join(''):'<div class="empty">这一天还没有任务，给重要的事留一段时间吧。</div>'}
function habitsView(manage=false){return state.habitDefinitions.map(h=>{const checked=habitDone(h.id);return `<div class="habit"><span class="habit-icon">✓</span><div class="habit-name">${esc(h.name)}<small>${h.id==='move'?'运动记录自动关联':h.id==='reflect'?'复盘记录自动关联':'每天一次'}</small></div><button data-habit="${h.id}" class="${checked?'checked':''}">${checked?'✓ 已完成':'打卡'}</button><button data-habit-backfill="${esc(h.id)}">补打卡</button>${manage?`<button data-habit-stats="${h.id}">统计</button><button data-habit-delete="${h.id}">删除</button>`:''}</div>`}).join('')||'<p class="empty">还没有习惯，在规划的习惯页添加一个吧。</p>'}
async function saveHabitBackfill(values){const h=state.habitDefinitions.find(h=>h.id===editing);if(!h){toast('该习惯已不存在');return}if(!values.date||values.date>today||values.date<h.startDate){showFieldError($('#form'),'date','请选择习惯开始日期至今天之间的日期');return}if(habitDone(h.id,values.date)){toast('这一天已经打卡，无需重复补录');return}const key=values.date+':'+h.id,prior=state.habits[key];state.habits[key]=true;if(!(await save())){if(prior===undefined)delete state.habits[key];else state.habits[key]=prior;toast('补打卡未保存，请重试');return}$('#dialog').close();render();toast('已补上 '+values.date+' 的打卡')}
document.addEventListener('click',e=>{const key=e.target.closest('button')?.dataset.habitBackfill;if(key){const h=state.habitDefinitions.find(h=>h.id===key);if(h)openForm('habitBackfill',h)}});
function habitDone(k,date=today){return !!state.habits[date+':'+k]||(k==='move'&&sum(state.workouts.filter(w=>w.date===date),'minutes')>=30)||(k==='reflect'&&state.reviews.some(r=>r.date===date))}
function habitMonthDays(h,year,month){return Array.from({length:new Date(year,month,0).getDate()},(_,i)=>{const date=year+'-'+String(month).padStart(2,'0')+'-'+String(i+1).padStart(2,'0');return {date,eligible:date<=today&&date>=h.startDate,done:habitDone(h.id,date)}})}
function habitStatistics(){const h=state.habitDefinitions.find(h=>h.id===habitSelected)||state.habitDefinitions[0];if(!h)return '';habitSelected=h.id;const year=Number(habitDate.slice(0,4)),month=Number(habitDate.slice(5,7)),all=Array.from({length:12},(_,i)=>habitMonthDays(h,year,i+1)),days=habitMode==='month'?all[month-1]:all.flat(),eligible=days.filter(d=>d.eligible),done=eligible.filter(d=>d.done).length;return `<section class="card habit-stats"><div class="card-head"><div class="habit-stats-heading"><select id="habit-stats-selector" aria-label="选择要查看统计的习惯">${state.habitDefinitions.map(item=>`<option value="${esc(item.id)}" ${item.id===h.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select><h2>· 打卡记录</h2></div></div><div class="card-body"><div class="plan-toolbar"><div class="tabs"><button data-habit-mode="month" class="${habitMode==='month'?'active':''}">月</button><button data-habit-mode="year" class="${habitMode==='year'?'active':''}">年</button></div><div><button data-habit-period="-1">←</button> ${habitMode==='month'?habitDate.slice(0,7):year} <button data-habit-period="1">→</button><button data-habit-period="0">当前</button></div></div><p>已打卡 <strong>${done}</strong> 天 / ${eligible.length} 个可打卡日 · 完成率 ${eligible.length?Math.round(done/eligible.length*100):0}%</p><p class="muted">按每天一次统计，排除未来与开始日期之前的天数。开始日期：${h.startDate}</p>${habitMode==='month'?`<div class="habit-calendar">${['一','二','三','四','五','六','日'].map(d=>`<span>周${d}</span>`).join('')}${'<span></span>'.repeat((new Date(year,month-1,1).getDay()+6)%7)}${days.map(d=>`<button data-habit-day="${d.date}" ${!d.eligible?'disabled':''} class="${d.done?'checked':''}" aria-label="${d.date} ${d.done?'已打卡':'未打卡'}">${Number(d.date.slice(-2))}<small>${d.done?'✓':d.eligible?'—':''}</small></button>`).join('')}</div><p class="muted">点击日期补打卡或撤销。自动完成的打卡请修改源运动／复盘记录。</p>`:`<div class="habit-year">${all.map((list,i)=>{const e=list.filter(d=>d.eligible),n=e.filter(d=>d.done).length;return `<button data-habit-month="${i+1}"><strong>${i+1} 月</strong><div class="progress"><i style="width:${e.length?n/e.length*100:0}%"></i></div><span>${n} / ${e.length} 天</span></button>`}).join('')}</div><p class="muted">点击月份查看每日记录。</p>`}</div></section>`}
function goalRows(){return state.goals.filter(g=>g.status!=='已归档').slice(0,2).map(g=>`<button class="planning-row" data-open-planning="${g.id}"><span>${esc(g.title)}</span><small>${planningType(g)} ↗</small></button>`).join('')||'<p class="muted">到规划页写下下一步方向。</p>'}

function todayTaskList(ts){const pending=ts.filter(t=>!t.done).sort((a,b)=>Number(!!b.priority)-Number(!!a.priority)),done=ts.filter(t=>t.done);return (pending.length?taskRows(pending):`<div class="empty">${ts.length?'今天的待办都已完成。':'今天还没有待办，添加一件事开始吧。'}</div>`)+(done.length?`<details class="completed-tasks"><summary>已完成（${done.length}）</summary>${taskRows(done)}</details>`:'')+`<button class="small-add" data-new-today>＋ 添加待办</button><p class="muted">点击星标设置重点，每天最多 3 项。</p>`}
function todayView(){let ts=tasksFor(today),spend=sum(state.money.filter(m=>m.date===today&&m.kind==='支出'),'amount');return heading('MAKE ROOM FOR WHAT MATTERS',`你好，${esc(state.user)} <span style="font-weight:400">☀</span>`,'从最重要的一件事开始，按自己的节奏前进。',`<div class="date-pill">${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</div>`)+`<div class="summary">${stat('今日任务',`${completed()} <span style="color:#b0b8c7;font-size:19px">/ ${ts.length}</span>`,'项','专注于小步向前','◷')}${stat('学习记录',sum(state.notes.filter(n=>n.date===today),'minutes'),'分钟','实际记录的学习时间','▤')}${stat('今日支出','¥ '+spend.toFixed(2),'','每一笔，都心中有数','◈')}${stat('习惯打卡',state.habitDefinitions.filter(h=>habitDone(h.id)).length,'/ '+state.habitDefinitions.length,'让坚持慢慢发生','◎')}</div><div class="dashboard"><div class="stack">${card('今日待办',todayTaskList(ts),`<span class="muted">已完成 ${ts.filter(t=>t.done).length} / ${ts.length}</span><button class="quiet" data-page="plan">查看日程 ↗</button>`)}${card('正在推进的规划',goalRows(),`<button class="quiet" data-page="goals">全部 ↗</button>`)}</div><div class="stack">${card('时间安排',timeline(ts),`<span class="muted">今天</span>`)}${card('每日习惯',habitsView(),`<span class="muted">${state.habitDefinitions.filter(h=>habitDone(h.id)).length}/${state.habitDefinitions.length}</span>`)}${card('给今天留几句话',`<p>记录一个收获，放下还没做完的事。<br>明天，也会有新的开始。</p><button data-action="review">写下今日复盘 ↗</button>`,'','review-card')}</div></div>`}
function scheduleAddsTasks(r){return r.addToTasks??(r.kind==='重复待办')}
function matchesSchedule(r,date){return r.dates?r.dates.includes(date):date>=r.startDate&&date<=r.endDate&&(r.weekdays||[]).includes(String(new Date(date+'T12:00:00').getDay()))}
function ensureRecurringTasks(date){for(const r of state.schedules){if(!scheduleAddsTasks(r)||!matchesSchedule(r,date)||(r.skips||[]).includes(date))continue;const taskId='repeat-'+r.id+'-'+date;if(!state.tasks.some(t=>t.id===taskId))state.tasks.push({id:taskId,seriesId:r.id,goalId:r.goalId||'',title:r.title,description:r.description||'',group:r.group||'其他',date,time:r.startTime,duration:minutes(r.endTime)-minutes(r.startTime),done:false})}}
function descriptionView(r){return r.description?`<details class="task-description"><summary>描述</summary><p class="notes-text">${esc(r.description)}</p></details>`:''}
function previousDate(date){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-1);return dayKey(d)}
function truncateSeries(series,from){if(from<=series.startDate)state.schedules=state.schedules.filter(r=>r.id!==series.id);else series.endDate=previousDate(from);state.tasks=state.tasks.filter(t=>t.seriesId!==series.id||t.date<from)}
async function saveRecurringSchedule(values){const before=structuredClone({tasks:state.tasks,schedules:state.schedules});const old=state.schedules.find(r=>r.id===editing);const from=values.effectiveDate||values.startDate;delete values.effectiveDate;if(old){if(from<today||from<old.startDate||from>old.endDate){toast('请选择原系列范围内、今天或以后的生效日期');return}values.linkKey=old.linkKey||old.id;truncateSeries(old,from);values.startDate=from}delete values.id;delete values.skips;state.schedules.push({...values,id:id()});if(!(await save())){Object.assign(state,before);toast('安排未保存，请重试');return}$('#dialog').close();render();toast('安排已保存')}
async function removeRecurring(values){const before=structuredClone({tasks:state.tasks,schedules:state.schedules});const t=state.tasks.find(r=>r.id===editing),series=state.schedules.find(r=>r.id===(t?.seriesId||editing));if(!series)return;if(series.startDate>series.endDate){state.schedules=state.schedules.filter(r=>r.id!==series.id);state.tasks=state.tasks.map(task=>{if(task.seriesId!==series.id)return task;const copy={...task};delete copy.seriesId;return copy});if(!(await save())){Object.assign(state,before);toast('删除未保存，请重试');return}$('#dialog').close();render();toast('异常安排已移除，已有任务保留');return}const from=t?.date||values.effectiveDate;if(!from||((!t||values.scope!=='仅这一次')&&from<today)||from<series.startDate||from>series.endDate){toast('请选择系列范围内、今天或以后的日期');return}if(t&&values.scope==='仅这一次'){series.skips=[...new Set([...(series.skips||[]),from])];state.tasks=state.tasks.filter(r=>r.id!==t.id)}else truncateSeries(series,from);if(!(await save())){Object.assign(state,before);toast('删除未保存，请重试');return}$('#dialog').close();render();toast('已删除所选安排，过去记录保留')}
function occurrences(date){const day=new Date(date+'T12:00:00').getDay();return state.schedules.filter(r=>!scheduleAddsTasks(r)&&matchesSchedule(r,date)).map(r=>({...r,fixed:true,group:'固定安排',time:r.startTime,duration:minutes(r.endTime)-minutes(r.startTime)}))}
function minutes(t){const [h,m]=t.split(':').map(Number);return h*60+m}
function timeline(ts,date=today){const a=[...ts.filter(t=>t.time),...occurrences(date)].sort((a,b)=>a.time.localeCompare(b.time));return a.length?`<div class="timeline">${a.map((t,i)=>`<div class="time-row"><span class="time-label">${t.time}</span><div class="event ${t.fixed?'green':['','purple','green'][i%3]}">${esc(t.title)}<small>${t.fixed?`${t.startTime}–${t.endTime} · 固定安排${t.place?' · '+esc(t.place):''}`:esc(t.group)+' · '+t.duration+' 分钟'} ${t.done?'· 已完成':''}</small>${descriptionView(t)}${t.fixed?`<button class="quiet" data-edit-schedule="${t.id}">编辑系列</button>`:''}</div></div>`).join('')}</div>`:'<div class="empty">暂未安排时间</div>'}
function planView(){const base=new Date(selectedDate+'T12:00:00'),offset=(base.getDay()+6)%7;let calendar='';if(planMode==='week'){calendar=`<div class="week">${Array.from({length:7},(_,i)=>{let d=new Date(base);d.setDate(base.getDate()-offset+i);let k=dayKey(d);return `<button class="day ${k===selectedDate?'active':''}" data-date="${k}"><small>周${['一','二','三','四','五','六','日'][i]}</small>${d.getMonth()+1}/${d.getDate()}<small>${tasksFor(k).length+occurrences(k).length} 项</small></button>`}).join('')}</div>`}else{let first=new Date(base.getFullYear(),base.getMonth(),1,12),start=new Date(first);start.setDate(1-(first.getDay()+6)%7);calendar=`<div class="month-grid">${['一','二','三','四','五','六','日'].map(d=>`<div class="month-heading">周${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);let k=dayKey(d),events=[...occurrences(k),...tasksFor(k)];return `<button class="month-day ${k===selectedDate?'selected':''} ${d.getMonth()!==base.getMonth()?'outside':''}" data-date="${k}" aria-label="${k}，${events.length}项安排"><span class="month-date-header"><span>${d.getDate()}${k===today?' · 今':''}</span><small class="lunar-date" title="农历${esc(lunarDate(k))}">${esc(lunarDate(k).replace(/^.*月(?!初一)/,''))}</small></span><span class="month-events">${events.slice(0,2).map(t=>`<span class="month-event">${esc(t.title)}</span>`).join('')}${events.length>2?`<span class="month-more">另 ${events.length-2} 项</span>`:''}</span></button>`}).join('')}</div>`}return heading('PLAN WITH INTENTION','把时间留给重要的事','按周或按月查看，固定课程与每日任务一起安排。',`<button data-action="new">＋ 新建任务</button>`)+`<div class="plan-toolbar"><div class="tabs"><button data-plan-mode="week" class="${planMode==='week'?'active':''}">周视图</button><button data-plan-mode="month" class="${planMode==='month'?'active':''}">月视图</button></div><div class="tabs"><button data-period="-1" aria-label="上一${planMode==='week'?'周':'月'}">←</button><strong>${base.getFullYear()} 年 ${base.getMonth()+1} 月</strong><button data-period="1" aria-label="下一${planMode==='week'?'周':'月'}">→</button><button data-period="0">今天</button></div><button class="primary" data-action="schedule">＋ 固定安排</button></div>${calendar}<div class="dashboard"><div>${card(selectedDate+' · 任务',taskRows(tasksFor(selectedDate)))}</div><div>${card('当日时间安排',timeline(tasksFor(selectedDate),selectedDate))}</div></div><div style="margin-top:22px">${card('固定安排',state.schedules.length?state.schedules.map(r=>`<div class="record-row"><div class="grow"><h3>${esc(r.title)}</h3><p>${r.startDate>r.endDate?'日期异常 · 请删除此无效安排':esc(r.startDate)+' 至 '+esc(r.endDate)} · 每周${r.weekdays.map(d=>['日','一','二','三','四','五','六'][d]).join('、')} · ${r.startTime}–${r.endTime}</p><p>${esc(r.place||'')}</p>${descriptionView(r)}${scheduleAddsTasks(r)?'<span class="tag">已添加到任务</span>':''}</div><button data-schedule-tasks="${esc(r.linkKey||r.id)}">相关任务 ${state.tasks.filter(t=>t.scheduleLinkId===(r.linkKey||r.id)).length}</button><button data-edit-schedule="${r.id}">编辑</button><button data-remove-series="${r.id}">删除安排</button></div>`).join(''):'<p class="muted">添加每周课程、组会或训练，设置日期范围后会自动显示在对应日期。</p>')}</div>`}
function tabs(items){return `<div class="tabs">${items.map(t=>`<button data-filter="${esc(t)}" class="${filter===t?'active':''}">${esc(t)}</button>`).join('')}</div>`}

function validNoteURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function noteLinkRow(link={}){return `<div class="note-link-row"><input data-link-name aria-label="链接名称" placeholder="名称，例如第三章笔记" maxlength="100" value="${esc(link.name||'')}"><input data-link-url aria-label="网页链接" placeholder="https://…" type="url" value="${esc(link.url||'')}"><button type="button" data-remove-link aria-label="移除链接">×</button></div>`}
function noteLinksEditor(links=[]){return `<details class="note-links-editor" ${links.length?'open':''}><summary>相关链接（可选）</summary><p class="muted">支持网页或笔记分享链接；应用专属链接暂不支持。</p><div id="note-link-rows">${links.map(noteLinkRow).join('')}</div><button type="button" data-add-link>＋ 添加链接</button><p id="note-link-error" role="alert"></p></details>`}
function noteLinksView(n){return (Array.isArray(n.links)?n.links:[]).filter(l=>validNoteURL(l.url)).map(l=>`<a class="note-resource" href="${esc(validNoteURL(l.url))}" target="_blank" rel="noopener noreferrer">${esc(l.name||new URL(l.url).hostname)} ↗</a>`).join('')}

function folderOf(note){return state.folders.find(f=>f.id===note.folderId&&f.group===note.group)?.id||'unfiled'}
function folderOptions(group,selected=''){return `<option value="">未分类</option>`+state.folders.filter(f=>f.group===group).map(f=>`<option value="${f.id}" ${selected===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}
function folderSelect(r){const group=r.group||(state.learningCategories.includes(filter)?filter:state.learningCategories[0]);return `<label for="f-folderId">所属文件夹</label><select name="folderId" id="f-folderId">${folderOptions(group,r.folderId||(learningFolder!=='unfiled'?learningFolder:''))}</select>`}
function learnView(){const groups=state.learningCategories;const headingHTML=heading('LEARN & DISCOVER','学习，是一场长期积累','按分类与文件夹整理，给每一份积累找到位置。',`<button class="primary" data-action="note">＋ 学习记录</button>`)+'<div class="plan-toolbar">'+tabs(['全部',...groups])+'<button data-action="categories">管理分类</button></div>';if(learningFolder&&filter!=='全部'){const name=learningFolder==='unfiled'?'未分类':state.folders.find(f=>f.id===learningFolder)?.name||'未分类';let arr=state.notes.filter(n=>n.group===filter&&folderOf(n)===learningFolder);return headingHTML+`<div class="folder-breadcrumb"><button data-folder-back>← 文件夹</button><span>${esc(filter)} / ${esc(name)}</span></div>`+(arr.length?`<div class="grid">${arr.map(n=>`<section class="card"><div class="card-top"><span class="tag ${n.group==='课程'?'purple':''}">${esc(n.group)}</span><span class="muted">▤</span></div><h3>${esc(n.title)}</h3><p class="notes-text">${esc(n.content)}</p><div class="note-resources">${noteLinksView(n)}</div>${attachmentView(n)}<div class="muted">${n.minutes?`学习 ${n.minutes} 分钟`:'学习空间 · 示例内容'}</div><div style="margin-top:20px"><button data-edit-note="${n.id}">打开记录 ↗</button></div></section>`).join('')}</div>`:'<div class="empty">这里还没有记录，点击“学习记录”添加。</div>')}
return headingHTML+groups.filter(g=>filter==='全部'||g===filter).map(g=>`<section class="folder-section"><div class="card-head"><h2>${esc(g)}</h2><button data-new-folder="${esc(g)}">＋ 新建文件夹</button></div><div class="grid">${[{id:'unfiled',name:'未分类'},...state.folders.filter(f=>f.group===g)].map(f=>`<section class="card folder-card"><button class="folder-open" data-open-folder="${f.id}" data-folder-group="${esc(g)}"><svg viewBox="0 0 24 24" width="32" height="32" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/></svg><h3>${esc(f.name)}</h3><span class="muted">${state.notes.filter(n=>n.group===g&&folderOf(n)===f.id).length} 条记录</span></button>${f.id!=='unfiled'?`<div class="folder-actions"><button data-rename-folder="${f.id}">重命名</button><button data-remove-folder="${f.id}">删除</button></div>`:''}</section>`).join('')}</div></section>`).join('')}
state.moneyCategories=state.moneyCategories||{};
for(const kind of ['收入','支出'])state.moneyCategories[kind]=[...new Set([...(state.moneyCategories[kind]||(kind==='收入'?['工资','补贴','奖学金','兼职']:['餐饮','交通','学习','购物','居住'])),...state.money.filter(m=>m.kind===kind).map(m=>m.category)].filter(c=>c&&c!=='其他'))];
