function shoppingFields(r={}){return select('subcategory','购物细分（可选）',['',...state.shoppingCategories,'其他'],r.subcategory||'')+'<div id="shopping-custom" hidden>'+field('customSubcategory','自定义购物细分','text','','maxlength="20" disabled')+'</div>'}
function moneyCategoryLabel(m){return esc(m.category)+(m.category==='购物'&&m.subcategory?' / '+esc(m.subcategory):'')}
function moneyCategoryFields(r){const options=[...state.moneyCategories[r.kind||'支出'],'其他'];return select('category','分类',options,r.category||options[0])+`<div id="money-custom" ${r.category==='其他'?'':'hidden'}>`+field('customCategory','自定义分类','text','','maxlength="20" '+(r.category==='其他'?'required':'disabled'))+'</div><div id="shopping-fields">'+((r.category||options[0])==='购物'?shoppingFields(r):'')+'</div>'}
function calculateMoney(raw){const text=String(raw??'').trim().replace(/＋/g,'+').replace(/[－−]/g,'-');if(text.length>200||!/^\d+(?:\.\d{1,2})?(?:\s*[+-]\s*\d+(?:\.\d{1,2})?)*$/.test(text))throw Error('请输入金额或加减算式，例如 59-10；每项最多两位小数');const parts=text.replace(/\s/g,'').match(/[+-]?\d+(?:\.\d{1,2})?/g);let cents=0;for(const part of parts){const sign=part[0]==='-'?-1:1;const [whole,fraction='']=part.replace(/^[+-]/,'').split('.');const n=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(n)||!Number.isSafeInteger(cents+sign*n))throw Error('金额过大');cents+=sign*n}if(cents<1||cents>9999999900)throw Error('计算结果须在 0.01 至 99999999 元之间');return cents/100}
function taskGroupFields(r){const options=[...new Set([...taskGroups.filter(x=>x!=='其他'),...state.tasks.map(t=>t.group).filter(x=>x&&x!=='其他'),...state.schedules.map(t=>t.group).filter(x=>x&&x!=='其他')]),'其他'];return select('group','所属领域',options,r.group)+'<div id="task-custom-group" '+(r.group==='其他'?'':'hidden')+'>'+field('customGroup','自定义类别','text','','maxlength="20" '+(r.group==='其他'?'required':'disabled'))+'</div>'}
