function moneyForm(r){return select('kind','类型',['支出','收入'],r.kind||'支出')+field('title','说明','text',r.title||'','required maxlength="100"')+field('amount','金额（人民币）','text',r.amount??'','required maxlength="200" placeholder="例如 59-10"')+'<p id="amount-result" class="muted" aria-live="polite">支持加减，例如 59-10，保存为 49 元。</p>'+'<div id="money-category-fields">'+moneyCategoryFields(r)+'</div>'+field('date','记账日期','date',r.date||(page==='finance'?financeDate:today),'required')}
function financeWeekDays(){const base=new Date(financeDate+'T12:00:00');base.setDate(base.getDate()-(base.getDay()+6)%7);return Array.from({length:7},(_,i)=>{const d=new Date(base);d.setDate(d.getDate()+i);return dayKey(d)})}
function financeDistribution(rows,title){const groups=new Map();for(const m of rows.filter(x=>x.kind==='支出')){const name=m.category==='购物'&&m.subcategory?`购物 / ${m.subcategory}`:(m.category||'未分类');groups.set(name,(groups.get(name)||0)+Number(m.amount||0))}const items=[...groups].sort((a,b)=>b[1]-a[1]),total=items.reduce((n,x)=>n+x[1],0),max=Math.max(1,...items.map(x=>x[1]));return card(title,items.length?`<p class="muted">按支出分类统计，共 ¥ ${total.toFixed(2)}</p><div class="finance-distribution">${items.map(([name,value])=>`<div class="finance-distribution-row"><div class="finance-distribution-label"><span>${esc(name)}</span><strong>¥ ${value.toFixed(2)}</strong></div><div class="finance-distribution-track"><i style="width:${value/max*100}%"></i></div><small class="muted">${(value/total*100).toFixed(1)}%</small></div>`).join('')}</div>`:'<p class="empty">所选时间段还没有支出记录。</p>')}
function financeView(){if(financeMode!=='week')return financePeriodView();const days=financeWeekDays(),all=state.money.filter(m=>days.includes(m.date)),rows=all.filter(m=>m.date===financeDate);return heading('MONEY, WITH CLARITY','每一笔，都有去处','先选择日期，再记录当天收支。','<button class="primary" data-action="money">＋ 记一笔</button>')+`<div class="plan-toolbar"><div class="tabs"><button class="active" data-finance-mode="week">周视图</button><button data-finance-mode="month">月视图</button><button data-finance-mode="year">年视图</button></div><div class="tabs"><button data-finance-period="-1">← 上周</button><span>${days[0]} 至 ${days[6]}</span><button data-finance-period="1">下周 →</button><button data-finance-period="0">今天</button></div></div><div class="week">${days.map((date,i)=>`<button class="day ${date===financeDate?'active':''}" data-finance-day="${date}"><small>周${['一','二','三','四','五','六','日'][i]}</small>${date.slice(5).replace('-','/')}<small>${all.filter(m=>m.date===date).length} 笔</small></button>`).join('')}</div><div class="summary">${stat('本周收入','¥ '+sum(all.filter(m=>m.kind==='收入'),'amount').toFixed(2),'','','↙')}${stat('本周支出','¥ '+sum(all.filter(m=>m.kind==='支出'),'amount').toFixed(2),'','','↗')}${stat('所选日收入','¥ '+sum(rows.filter(m=>m.kind==='收入'),'amount').toFixed(2),'',financeDate,'↙')}${stat('所选日支出','¥ '+sum(rows.filter(m=>m.kind==='支出'),'amount').toFixed(2),'',financeDate,'↗')}</div>`+financeDistribution(all,'本周支出分布')+card(financeDate+' · 收支记录',rows.map(m=>`<div class="record-row"><div class="grow">${esc(m.title)}<p>${moneyCategoryLabel(m)} · ${esc(m.kind)}</p></div><span>¥ ${Number(m.amount).toFixed(2)}</span><button data-edit-money="${m.id}">编辑</button><button data-delete="money:${m.id}">删除</button></div>`).join('')||'<p class="empty">当天暂无记录，点击「记一笔」补录。</p>')}
async function saveMoney(values){try{values.amount=calculateMoney(values.amount)}catch(error){showFieldError($('#form'),'amount',error.message);return}const prior=structuredClone({money:state.money,moneyCategories:state.moneyCategories,shoppingCategories:state.shoppingCategories});if(values.category==='其他'){const name=values.customCategory?.trim();if(!name||name.length>20||name==='其他'){showFieldError($('#form'),'customCategory','请填写具体分类名称（1–20字）');return}values.category=name;if(!state.moneyCategories[values.kind].includes(name))state.moneyCategories[values.kind].push(name)}delete values.customCategory;if(values.category==='购物'){if(values.subcategory==='其他'){const name=values.customSubcategory?.trim();if(!name||name.length>20||name==='其他'){Object.assign(state,prior);showFieldError($('#form'),'customSubcategory','请填写具体购物细分名称（1–20字）');return}values.subcategory=name;if(!state.shoppingCategories.includes(name))state.shoppingCategories.push(name)}else values.subcategory=values.subcategory||''}else values.subcategory='';delete values.customSubcategory;values.amount=Math.round(Number(values.amount)*100)/100;if(editing)Object.assign(state.money.find(m=>m.id===editing),values);else state.money.unshift({id:id(),...values});if(!(await save())){Object.assign(state,prior);toast('未保存，请重试');return}if(page==='finance')financeDate=values.date;$('#dialog').close();render();toast('收支已保存')}
document.addEventListener('change',e=>{if(formType!=='money')return;if(e.target.name==='kind')$('#money-category-fields').innerHTML=moneyCategoryFields({kind:e.target.value});if(e.target.name==='subcategory'){const custom=e.target.value==='其他';$('#shopping-custom').hidden=!custom;$('#f-customSubcategory').disabled=!custom;$('#f-customSubcategory').required=custom;if(custom)$('#f-customSubcategory').focus()}if(e.target.name==='category'){$('#shopping-fields').innerHTML=e.target.value==='购物'?shoppingFields():'';const custom=e.target.value==='其他';$('#money-custom').hidden=!custom;$('#f-customCategory').disabled=!custom;$('#f-customCategory').required=custom;if(custom)$('#f-customCategory').focus()}});
document.addEventListener('click',async e=>{const name=e.target.closest('button')?.dataset.deleteWorkoutType;if(!name)return;if(!confirm('删除自定义运动类型“'+name+'”？已有记录不会删除。'))return;const index=state.workoutTypes.indexOf(name);if(index<0)return;state.workoutTypes.splice(index,1);if(!(await save())){state.workoutTypes.splice(index,0,name);toast('删除未保存，请重试');return}openForm('workoutTypes');toast('已删除自定义运动类型')});
