function financePeriodView(){const period=financeDate.slice(0,financeMode==='year'?4:7),a=state.money.filter(m=>m.date.startsWith(period)),expense=sum(a.filter(x=>x.kind==='支出'),'amount'),income=sum(a.filter(x=>x.kind==='收入'),'amount');const count=financeMode==='year'?12:new Date(Number(financeDate.slice(0,4)),Number(financeDate.slice(5,7)),0).getDate();const buckets=Array.from({length:count},(_,i)=>{const key=period+'-'+String(i+1).padStart(2,'0'),rows=a.filter(m=>m.date.startsWith(key));return {label:String(i+1)+(financeMode==='year'?'月':'日'),income:sum(rows.filter(m=>m.kind==='收入'),'amount'),expense:sum(rows.filter(m=>m.kind==='支出'),'amount')}}),max=Math.max(1,...buckets.flatMap(b=>[b.income,b.expense]));return heading('MONEY, WITH CLARITY','每一笔，都有去处','在月度细节与年度变化之间，了解自己的收支。',`<button class="primary" data-action="money">＋ 记一笔</button>`)+`<div class="plan-toolbar"><div class="tabs"><button data-finance-mode="week">周视图</button><button data-finance-mode="month" class="${financeMode==='month'?'active':''}">月视图</button><button data-finance-mode="year" class="${financeMode==='year'?'active':''}">年视图</button></div><div class="tabs"><button data-finance-period="-1" aria-label="上一期间">←</button><strong>${period}</strong><button data-finance-period="1" aria-label="下一期间">→</button><button data-finance-period="0">当前${financeMode==='year'?'年':'月'}</button></div></div><div class="summary">${stat('期间收入','¥ '+income.toFixed(2),'',period,'↙')}${stat('期间支出','¥ '+expense.toFixed(2),'',period,'↗')}${stat('期间结余','¥ '+(income-expense).toFixed(2),'','收入减去支出','◈')}${stat('期间记录',a.length,'笔','按所选期间统计','▤')}</div>`+card(financeMode==='year'?'每月收支':'每日收支',`<p class="muted">绿色：收入 · 主题色：支出 · 单位：元</p><div class="finance-chart">${buckets.map(b=>`<div class="finance-bar-group" title="${b.label} 收入 ${b.income.toFixed(2)} 元；支出 ${b.expense.toFixed(2)} 元"><div class="finance-bars"><i class="income-bar" style="height:${b.income/max*130}px"></i><i style="height:${b.expense/max*130}px"></i></div><small>${b.label}</small></div>`).join('')}</div><details><summary>查看精确数据</summary><div class="finance-table"><table><thead><tr><th>时间</th><th>收入</th><th>支出</th><th>结余</th></tr></thead><tbody>${buckets.map(b=>`<tr><td>${b.label}</td><td>${b.income.toFixed(2)}</td><td>${b.expense.toFixed(2)}</td><td>${(b.income-b.expense).toFixed(2)}</td></tr>`).join('')}</tbody></table></div></details>`)+financeDistribution(a,financeMode==='year'?'本年度支出分布':'本月支出分布')+`<div style="margin-top:22px">`+card('期间收支记录',a.length?a.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<div class="record-row"><span class="habit-icon">${m.kind==='收入'?'↙':'↗'}</span><div class="grow">${esc(m.title)}<p>${m.date} · ${moneyCategoryLabel(m)}</p></div><span>${m.kind==='收入'?'+':'−'} ¥ ${Number(m.amount).toFixed(2)}</span><button data-edit-money="${m.id}">编辑</button><button class="quiet" data-delete="money:${m.id}" aria-label="删除记录">×</button></div>`).join(''):'<div class="empty">所选期间还没有收支记录。</div>')+'</div>'}
