function periodView(){const records=state.periods.slice().sort((a,b)=>b.start.localeCompare(a.start));const count=new Date(Number(periodMonth.slice(0,4)),Number(periodMonth.slice(5,7)),0).getDate(),offset=(new Date(periodMonth+'-01T12:00:00').getDay()+6)%7;return heading('HEALTH JOURNAL','经期记录','记录实际日期和感受；不进行预测。',`<button class="primary" data-action="period">＋ 记录经期</button>`)+`<div class="plan-toolbar"><button data-period-month="-1" aria-label="上个月">←</button><strong>${periodMonth}</strong><button data-period-month="1" aria-label="下个月">→</button><button data-period-month="0">本月</button></div>`+card('月历',`<p class="muted">底色表示已记录的经期，圆点表示有每日记录。点击日期补录当天情况。</p><div class="period-calendar">${['一','二','三','四','五','六','日'].map(d=>`<span>周${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const date=periodMonth+'-'+String(i+1).padStart(2,'0'),active=records.some(r=>r.start<=date&&date<=(r.end||today)),daily=state.periodDays.some(r=>r.date===date);return `<button ${date>today?'disabled':''} data-period-day="${date}" class="${active?'period-active':''}" aria-label="${date}${active?' 经期':''}${daily?' 有记录':''}">${i+1}${daily?' ·':''}</button>`}).join('')}</div>`)+`<div style="margin-top:22px">`+card('历史经期与间隔',records.length?records.map((r,i)=>`<div class="record-row"><div class="grow"><strong>${esc(r.start)} — ${esc(r.end||'尚未填写结束日期')}</strong><p>${r.end?'持续 '+(dateDays(r.start,r.end)+1)+' 天':'结束后可编辑补填'}${records[i+1]?' · 与上次开始相隔 '+dateDays(records[i+1].start,r.start)+' 天':''}</p></div><button data-edit-period="${r.id}">编辑</button><button data-delete="periods:${r.id}">删除</button></div>`).join(''):'<div class="empty">还没有经期记录，可以补录过去的日期。</div>')+'</div><div style="margin-top:22px">'+card('本月每日情况',state.periodDays.filter(r=>r.date.startsWith(periodMonth)).sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<div class="record-row"><div class="grow"><strong>${esc(r.date)}</strong><p>经量：${esc(r.flow)} · 疼痛：${esc(r.pain)}</p><p class="notes-text">${esc(r.notes)}</p></div><button data-period-day="${r.date}">编辑</button><button data-delete="periodDays:${r.id}">删除</button></div>`).join('')||'<div class="empty">点击月历日期，记录当天情况。</div>')+'</div>'}
