async function savePeriodForm(values){const key=formType==='period'?'periods':'periodDays';if(key==='periods'){if(!values.start||values.start>today||(values.end&&(values.end<values.start||values.end>today))){toast('请检查经期起止日期');return}if(state.periods.some(r=>r.id!==editing&&values.start<=(r.end||today)&&r.start<=(values.end||today))){toast('日期与已有经期重叠，请编辑已有记录');return}}else if(!values.date||values.date>today){toast('请选择今天或过去的日期');return}const previous=state[key];const found=previous.find(r=>r.id===editing||(key==='periodDays'&&r.date===values.date));state[key]=found?previous.map(r=>r.id===found.id?{...r,...values}:r):[...previous,{id:id(),...values}];if(!(await save())){state[key]=previous;toast('未保存，请重试');return}$('#dialog').close();render();toast('记录已保存')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.healthTab){healthTab=d.healthTab;render()}if('periodToggle'in d){const old=state.periodEnabled;state.periodEnabled=!old;if(!(await save())){state.periodEnabled=old;return}healthTab=state.periodEnabled?'period':'workout';render();toast(state.periodEnabled?'经期记录已开启':'已隐藏，记录仍保留')}if(d.periodMonth){const date=new Date(periodMonth+'-01T12:00:00');date.setMonth(date.getMonth()+Number(d.periodMonth));periodMonth=d.periodMonth==='0'?today.slice(0,7):dayKey(date).slice(0,7);render()}if(d.editPeriod)openForm('period',state.periods.find(r=>r.id===d.editPeriod));if(d.periodDay)openForm('periodDay',state.periodDays.find(r=>r.date===d.periodDay)||{date:d.periodDay})});

const defaultWorkoutTypes=['跑步','散步','力量训练','骑行','游泳'];state.workoutTypes=Array.isArray(state.workoutTypes)?state.workoutTypes.filter(x=>typeof x==='string'&&x&&x!=='其他'):[];for(const w of state.workouts||[])if(w.title&&!defaultWorkoutTypes.includes(w.title)&&!state.workoutTypes.includes(w.title))state.workoutTypes.push(w.title);const workoutTypes=[...defaultWorkoutTypes,...state.workoutTypes];
let workoutMode='week',workoutDate=today;
function workoutPeriod(){const start=new Date(workoutDate+'T12:00:00');if(workoutMode==='month')start.setDate(1);else start.setDate(start.getDate()-(start.getDay()+6)%7);const count=workoutMode==='month'?new Date(start.getFullYear(),start.getMonth()+1,0).getDate():7;return Array.from({length:count},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);return dayKey(d)})}
function workoutTypesManager(){return '<p class="muted">自定义运动类型会出现在运动记录下拉框中；已有记录不会受删除影响。</p><div class="workout-type-manager">'+(state.workoutTypes.length?state.workoutTypes.map(name=>`<div class="record-row"><span class="grow">${esc(name)}</span><button type="button" data-delete-workout-type="${esc(name)}">删除</button></div>`).join(''):'<p class="empty">还没有自定义运动类型。</p>')+'</div>'}
function workoutTypeFields(r){const custom=!!r.title&&!workoutTypes.includes(r.title);return select('title','运动类型',[...defaultWorkoutTypes,...state.workoutTypes,'其他'],custom?'其他':r.title||'跑步')+'<button type="button" class="quiet workout-type-manage-link" data-action="workoutTypes">管理自定义类型</button>'+`<div id="custom-workout" ${custom?'':'hidden'}>`+field('customTitle','运动名称','text',custom&&r.title!=='其他'?r.title:'',`maxlength="40" placeholder="例如：网球、乒乓球" ${custom?'required':'disabled'}`)+'</div>'}
function workoutView(){const days=workoutPeriod(),rows=state.workouts.filter(w=>days.includes(w.date)),buckets=days.map(date=>({date,minutes:sum(rows.filter(w=>w.date===date),'minutes')})),max=Math.max(1,...buckets.map(b=>b.minutes));return heading('MOVE & FEEL GOOD','让身体，也跟上节奏','记录运动，也记录自己的进步。',`<button class="primary" data-action="workout">＋ 记录运动</button>`)+`<div class="plan-toolbar"><div class="tabs"><button data-workout-mode="week" class="${workoutMode==='week'?'active':''}">周视图</button><button data-workout-mode="month" class="${workoutMode==='month'?'active':''}">月视图</button></div><div class="tabs"><button data-workout-period="-1" aria-label="上一期间">←</button><strong>${workoutMode==='month'?days[0].slice(0,7):days[0]+' 至 '+days[6]}</strong><button data-workout-period="1" aria-label="下一期间">→</button><button data-workout-period="0">当前${workoutMode==='week'?'周':'月'}</button></div></div><div class="summary">${stat('运动次数',rows.length,'次','所选期间','↗')}${stat('运动时长',sum(rows,'minutes'),'分钟','所选期间','◷')}${stat('记录热量',sum(rows,'calories'),'千卡','仅累计已填写的热量','↗')}${stat('运动天数',new Set(rows.map(w=>w.date)).size,'天','所选期间','✓')}</div>`+card('每日运动时长',`<p class="muted">单位：分钟；热量由你填写，不自动估算。</p><div class="finance-chart">${buckets.map(b=>`<div class="finance-bar-group" title="${b.date}：${b.minutes} 分钟"><small>${b.minutes}</small><div class="finance-bars"><i style="height:${b.minutes/max*130}px"></i></div><small>${Number(b.date.slice(5,7))}/${Number(b.date.slice(8))}</small><small class="lunar-date">${esc(lunarDate(b.date))}</small></div>`).join('')}</div>`)+`<div style="margin-top:22px">`+card('期间运动记录',rows.length?rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(w=>`<div class="record-row"><span class="habit-icon">↗</span><div class="grow">${esc(w.title)}<p>${esc(w.date)} · ${w.minutes} 分钟 ${w.calories!=null?'· '+Number(w.calories)+' 千卡':''}</p>${w.details?`<details class="workout-details"><summary>查看详情</summary><p class="notes-text">${esc(w.details)}</p></details>`:''}</div><button data-edit-workout="${w.id}">${w.details?'编辑':'添加详情'}</button><button class="quiet" data-delete="workouts:${w.id}" aria-label="删除运动">×</button></div>`).join(''):'<div class="empty">所选期间还没有运动记录。</div>')+'</div>'}

function ideasView(){return heading('A PLACE FOR POSSIBILITY','先记下来，让想法生长','不急着实现，每一个念头都有自己的时机。',`<button class="primary" data-action="idea">＋ 记下灵感</button>`)+`<div class="grid">${state.ideas.map(n=>`<section class="card"><div class="card-top"><span class="tag orange">${esc(n.tag||'随手记')}</span><button class="quiet" data-delete="ideas:${n.id}" aria-label="删除灵感">×</button></div><h3>${esc(n.title)}</h3><p class="notes-text">${esc(n.content)}</p><button data-convert="${n.id}" ${n.taskId?'disabled':''}>${n.taskId?'✓ 已关联任务':'转为今日任务 ↗'}</button></section>`).join('')}</div>`}
let planningTab='plans',planningFilter='全部',planningSelected=null;
function planningType(g){return g.horizon||(g.period==='长期'||g.period==='今年'?'长期':'短期')}
function planningPicker(value=''){return '<label for="f-goalId">关联规划（可选）</label><select name="goalId" id="f-goalId"><option value="">不关联</option>'+state.goals.map(g=>`<option value="${esc(g.id)}" ${g.id===value?'selected':''}>${esc(g.title)}</option>`).join('')+'</select>'}
function planningLinks(g){return ['tasks','schedules','habitDefinitions'].map((key,i)=>`<fieldset class="planning-links"><legend>${['每日任务','固定安排','习惯'][i]}</legend>${state[key].filter(r=>key!=='tasks'||!r.seriesId).map(r=>`<label><input type="checkbox" name="link-${key}" value="${esc(r.id)}" ${r.goalId===g.id?'checked':''}>${esc(r.title||r.name)}${r.date?' · '+esc(r.date):''}${r.goalId&&r.goalId!==g.id?'（当前属于其他规划）':''}</label>`).join('')||'<p class="muted">暂无记录，可先新增。</p>'}</fieldset>`).join('')+'<p class="muted">勾选会将该记录关联至本规划，不复制记录；取消勾选只解除关联。</p>'}
function planningProgress(g){const entries=[...(Array.isArray(g.updates)?g.updates:[])].sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''));return '<section class="planning-progress">'+card('进展记录',`<button data-progress-new="${esc(g.id)}">＋ 记录进展</button>`+(entries.length?entries.map(r=>`<article class="progress-entry"><div class="progress-entry-head"><time>${esc(r.date)}</time><span><button class="quiet" data-progress-edit="${esc(r.id)}" data-progress-goal="${esc(g.id)}">编辑</button><button class="quiet" data-progress-delete="${esc(r.id)}" data-progress-goal="${esc(g.id)}">删除</button></span></div><p class="notes-text">${esc(r.content)}</p></article>`).join(''):'<p class="muted">记下这次的进展。有下一步想法，也可以一起写。</p>'))+'</section>'}
async function saveProgress(values){const g=state.goals.find(g=>g.id===values.goalId);if(!g){toast('该规划已不存在，请关闭后重新打开');return}const before=structuredClone(g.updates||[]);if(formType==='progressDelete'){g.updates=before.filter(r=>r.id!==editing)}else{if(!values.content?.trim()){showFieldError($('#form'),'content','请填写进展内容');return}const entry={id:editing||id(),date:values.date,content:values.content.trim(),createdAt:new Date().toISOString()};g.updates=structuredClone(before);const old=g.updates.find(r=>r.id===editing);if(old)Object.assign(old,{date:entry.date,content:entry.content});else g.updates.push(entry)}if(!(await save())){g.updates=before;toast('进展未保存，填写内容仍保留，请重试');return}$('#dialog').close();render();toast(formType==='progressDelete'?'进展已删除':'进展已保存')}
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.progressNew)openForm('progress',{goalId:d.progressNew});if(d.progressEdit||d.progressDelete){const g=state.goals.find(g=>g.id===d.progressGoal),entry=g?.updates?.find(r=>r.id===(d.progressEdit||d.progressDelete));if(entry)openForm(d.progressDelete?'progressDelete':'progress',{...entry,goalId:g.id})}});
function planningDetails(g){const tasks=state.tasks.filter(t=>t.goalId===g.id),habits=state.habitDefinitions.filter(h=>h.goalId===g.id),schedules=state.schedules.filter(r=>r.goalId===g.id);return `<button class="quiet" data-planning-back>← 全部规划</button>`+heading(planningType(g)+'规划',esc(g.title),esc(g.status||'进行中'),`<div class="planning-toolbar"><button data-edit-goal="${g.id}">编辑规划</button><button data-action="planningLinks" data-planning-id="${g.id}">关联已有行动</button><button data-manage-planning="${g.id}">归档／删除</button></div>`)+card('规划内容',`<p class="muted">${esc(g.startDate||'未设开始日期')} 至 ${esc(g.endDate||'不限日期')}</p><p class="notes-text">${esc(g.content||'还没有写规划内容，点击编辑补充。')}</p>${g.parentId?'<p>所属长期规划：'+esc(state.goals.find(x=>x.id===g.parentId)?.title||'已移除')+'</p>':''}${state.goals.filter(x=>x.parentId===g.id).map(x=>`<button data-open-planning="${x.id}">${esc(x.title)} ↗</button>`).join('')}`)+planningProgress(g)+`<div class="planning-actions">${card('关联任务',`<p class="muted">已完成 ${tasks.filter(t=>t.done).length} / ${tasks.length} 项（已生成任务）</p>`+taskRows(tasks)+`<button data-planning-new="task" data-planning-id="${g.id}">＋ 添加任务</button>`)}${card('固定安排',schedules.map(r=>`<div class="record-row"><span class="grow">${esc(r.title)}</span><button data-edit-schedule="${r.id}">编辑</button></div>`).join('')+`<button data-planning-new="schedule" data-planning-id="${g.id}">＋ 添加固定安排</button>`)}${card('关联习惯',habits.map(h=>{const count=Object.keys(state.habits).filter(k=>k.endsWith(':'+h.id)&&state.habits[k]).length;return `<div class="record-row"><span class="grow">${esc(h.name)}<small> · 手动打卡累计 ${count} 天 · 今日${habitDone(h.id)?'已完成':'未完成'}</small></span><button data-habit="${h.id}">${habitDone(h.id)?'已完成':'打卡'}</button><button data-planning-habit="${h.id}">统计</button></div>`}).join('')+`<button data-planning-new="habitdef" data-planning-id="${g.id}">＋ 添加习惯</button>`)}</div>`}
function goalsView(){const tabs=`<div class="tabs"><button data-planning-tab="plans" class="${planningTab==='plans'?'active':''}">个人规划</button><button data-planning-tab="habits" class="${planningTab==='habits'?'active':''}">习惯</button></div>`;if(planningTab==='habits')return tabs+heading('HABITS','习惯打卡','让日常行动持续积累。')+card('我的习惯',habitsView(true)+'<button data-action="habitdef">＋ 新增习惯</button>')+habitStatistics();const g=state.goals.find(g=>g.id===planningSelected);if(g)return tabs+planningDetails(g);return tabs+heading('PERSONAL PLANNING','写下方向，安排下一步','把短期行动和长期规划连接起来。','<button class="primary" data-action="goal">＋ 新建规划</button>')+`<div class="tabs">${['全部','短期','长期','已归档'].map(x=>`<button data-planning-filter="${x}" class="${planningFilter===x?'active':''}">${x}</button>`).join('')}</div>`+card('我的规划',state.goals.filter(g=>planningFilter==='已归档'?g.status==='已归档':g.status!=='已归档'&&(planningFilter==='全部'||planningType(g)===planningFilter)).map(g=>`<button class="planning-row" data-open-planning="${g.id}"><span><strong>${esc(g.title)}</strong><small>${planningType(g)} · ${esc(g.endDate||g.period||'未设截止日期')}</small></span><span>${esc(g.status||'进行中')} ↗</span></button>`).join('')||'<p class="empty">写下一个近期或长期规划，开始安排下一步。</p>')}
async function savePlanning(values,form){const before=structuredClone({goals:state.goals,tasks:state.tasks,schedules:state.schedules,habitDefinitions:state.habitDefinitions});const g=state.goals.find(g=>g.id===editing);if(formType==='goal'){if(values.startDate&&values.endDate&&values.startDate>values.endDate){showFieldError(form,'endDate','结束日期不能早于开始日期');return}if(values.parentId&&(values.horizon!=='短期'||!state.goals.some(x=>x.id===values.parentId&&x.id!==editing&&planningType(x)==='长期'&&!x.parentId))){toast('短期规划只能关联一个长期规划');return}if(g&&values.horizon==='短期'&&state.goals.some(x=>x.parentId===g.id)){toast('请先解除其下的短期规划，再修改类型');return}if(g)Object.assign(g,values);else{const entry={id:id(),...values};state.goals.push(entry);planningSelected=entry.id}}else if(formType==='planningLinks'&&g){for(const key of ['tasks','schedules','habitDefinitions']){const selected=new Set(new FormData(form).getAll('link-'+key));for(const r of state[key]){if(key==='tasks'&&r.seriesId)continue;if(selected.has(r.id))r.goalId=g.id;else if(r.goalId===g.id)r.goalId=''}}for(const t of state.tasks.filter(t=>t.seriesId)){const r=state.schedules.find(r=>r.id===t.seriesId);if(r)t.goalId=r.goalId||''}}else if(formType==='planningManage'&&g){if(values.operation==='归档')g.status='已归档';else{state.goals=state.goals.filter(x=>x.id!==g.id);state.goals.forEach(x=>{if(x.parentId===g.id)x.parentId=''});for(const key of ['tasks','schedules','habitDefinitions'])state[key].forEach(r=>{if(r.goalId===g.id)r.goalId=''})}planningSelected=null}if(!(await save())){Object.assign(state,before);toast('规划未保存，请重试');return}$('#dialog').close();render();toast('规划已保存')}
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.planningTab){planningTab=d.planningTab;render()}if(d.planningFilter){planningFilter=d.planningFilter;render()}if(d.openPlanning){planningSelected=d.openPlanning;planningTab='plans';page='goals';render()}if('planningBack'in d){planningSelected=null;render()}if(d.planningNew)openForm(d.planningNew,{goalId:d.planningId});if(d.managePlanning)openForm('planningManage',state.goals.find(g=>g.id===d.managePlanning));if(d.planningHabit){habitSelected=d.planningHabit;planningTab='habits';render()}});

let reviewDate=today,reviewMode='week',reviewSelected=null,reviewBusy=false,reviewDeleteConfirm=false;
const reviewDrafts=new Map();
function reviewRecord(){const list=state.reviews.filter(r=>r.date===reviewDate);return list.find(r=>r.id===reviewSelected)||list[0]}
function reviewKey(){return reviewRecord()?.id||'new-'+reviewDate}
function reviewDays(){const d=new Date(reviewDate+'T12:00:00');if(reviewMode==='month')d.setDate(1);else d.setDate(d.getDate()-(d.getDay()+6)%7);const count=reviewMode==='month'?new Date(d.getFullYear(),d.getMonth()+1,0).getDate():7;return Array.from({length:count},(_,i)=>{const date=new Date(d);date.setDate(date.getDate()+i);return dayKey(date)})}
function reviewView(){const days=reviewDays(),r=reviewRecord(),list=state.reviews.filter(r=>r.date===reviewDate),draft=reviewDrafts.get(reviewKey()),content=draft??r?.content??'';const offset=reviewMode==='month'?(new Date(days[0]+'T12:00:00').getDay()+6)%7:0;return heading('REFLECT','留一点时间，写给自己','选择日期，自由写下想记录的内容。')+`<div class="plan-toolbar"><div class="tabs"><button data-review-mode="week" class="${reviewMode==='week'?'active':''}">周视图</button><button data-review-mode="month" class="${reviewMode==='month'?'active':''}">月视图</button></div><div class="tabs"><button data-review-period="-1">←</button><strong>${reviewMode==='month'?reviewDate.slice(0,7):days[0]+' 至 '+days[6]}</strong><button data-review-period="1">→</button><button data-review-period="0">今天</button></div></div><div class="${reviewMode==='month'?'review-calendar':'week'}">${reviewMode==='month'?['一','二','三','四','五','六','日'].map(d=>`<span>周${d}</span>`).join('')+'<span></span>'.repeat(offset):''}${days.map((date,i)=>`<button class="day ${date===reviewDate?'active':''}" data-review-date="${date}">${reviewMode==='week'?'<small>周'+['一','二','三','四','五','六','日'][i]+'</small>':''}${reviewMode==='month'?Number(date.slice(8)):date.slice(5).replace('-','/')}<small>${state.reviews.some(r=>r.date===date)?'● 已记录':'　'}</small></button>`).join('')}</div>`+card(reviewDate+' · 复盘',`${list.length>1?'<p class="muted">这一天有多篇历史记录，可分别查看和编辑。</p><div class="tabs">'+list.map((x,i)=>`<button data-review-record="${x.id}" class="${x.id===r?.id?'active':''}">${esc(x.title||'记录 '+(i+1))}</button>`).join('')+'</div>':''}<label for="review-writing" class="muted">想写什么，就从这里开始</label><textarea id="review-writing" rows="12" placeholder="写下今天的想法……" ${reviewBusy?'disabled':''}>${esc(content)}</textarea><div class="plan-toolbar"><span id="review-draft-status" class="muted">${draft!==undefined?'有未保存的内容':r?'已保存':'还没有记录'}</span><div class="tabs"><button class="primary" data-review-save ${reviewBusy?'disabled':''}>${reviewBusy?'保存中…':'保存'}</button>${r?`<button data-review-remove ${reviewBusy?'disabled':''}>删除</button>`:''}</div></div>${reviewDeleteConfirm?'<p>确认删除当前这篇复盘？</p><button data-review-confirm-delete>确认删除</button><button data-review-cancel-delete>取消</button>':''}`)}
async function persistReview(remove=false){if(reviewBusy)return;const r=reviewRecord(),key=reviewKey(),raw=reviewDrafts.get(key)??r?.content??'';if(!remove&&!raw.trim()){toast('请先写一点内容；删除已有记录请点击删除');$('#review-writing').focus();return}const before=structuredClone(state.reviews);reviewBusy=true;if(remove)state.reviews=state.reviews.filter(x=>x.id!==r?.id);else if(r)r.content=raw;else state.reviews.unshift({id:id(),date:reviewDate,title:'',content:raw});render();try{if(!(await save())){state.reviews=before;toast('未保存，文字仍保留，请重试');return}reviewDrafts.delete(key);reviewSelected=null;reviewDeleteConfirm=false;toast(remove?'复盘已删除':'复盘已保存')}finally{reviewBusy=false;render()}}
document.addEventListener('input',e=>{if(e.target.id!=='review-writing')return;reviewDrafts.set(reviewKey(),e.target.value);$('#review-draft-status').textContent='有未保存的内容'});
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(reviewBusy)return;if(d.reviewMode){reviewMode=d.reviewMode;reviewDeleteConfirm=false;render()}if(d.reviewDate){reviewDate=d.reviewDate;reviewSelected=null;reviewDeleteConfirm=false;render()}if(d.reviewRecord){reviewSelected=d.reviewRecord;reviewDeleteConfirm=false;render()}if(d.reviewPeriod){const date=new Date(reviewDate+'T12:00:00');if(reviewMode==='month'){date.setDate(1);date.setMonth(date.getMonth()+Number(d.reviewPeriod))}else date.setDate(date.getDate()+7*Number(d.reviewPeriod));reviewDate=d.reviewPeriod==='0'?today:dayKey(date);reviewSelected=null;reviewDeleteConfirm=false;render()}if('reviewSave'in d)persistReview();if('reviewRemove'in d){reviewDeleteConfirm=true;render()}if('reviewCancelDelete'in d){reviewDeleteConfirm=false;render()}if('reviewConfirmDelete'in d)persistReview(true)});
window.addEventListener?.('beforeunload',e=>{if(reviewDrafts.size){e.preventDefault();e.returnValue=''}});

function exploreView(){return heading('YOUR SPACE','探索你的工作台','学习、生活与未来，在这里相遇。')+`<div class="grid">${nav.slice(2).map(([k,i,n])=>`<button class="card" style="text-align:left" data-page="${k}" title="${n}" aria-label="${n}"><span class="icon">${icon(k)}</span><h3 style="margin:15px 0 0">${n} ↗</h3></button>`).join('')}</div>`}
function settingsView(){return heading('MAKE IT YOURS','这是你的空间','用熟悉的名字和喜欢的方式，开始每一天。')+`<div class="settings-grid"><section class="card"><h3>工作台外观与个人资料</h3><p class="muted">也可以点击左上角的工作台名称修改。</p><div class="setting-line"><div class="profile" style="border:0;padding:0">${avatar()}<div><h3>${esc(state.user)}</h3><span class="muted">${esc(state.name)}</span></div></div><button data-action="profile">名称、头像与图标</button></div></section>${palettePicker()}<section class="card"><div class="setting-line"><div><h3>深色外观</h3><span class="muted">调整工作台的显示方式</span></div><button data-action="theme">${state.dark?'已开启 · 关闭':'开启'}</button></div></section><section class="card">${window.gradlifeCloud?'<h3>邮箱账号与云端数据</h3><p class="muted">'+esc(window.gradlifeCloud.email)+' · 保存后可在其他设备刷新读取。PDF 云存储接入前，请暂用相关链接。</p>':'<h3>本机工作台</h3><p class="muted">数据只保存在当前浏览器。<a href="cloud.html">进入邮箱登录版</a>；本机数据不会自动上传。</p>'}<button data-action="export">导出数据</button></section></div>`}
function field(name,label,type='text',value='',extra=''){return `<label for="f-${name}">${label}${extra.includes('required')?'（必填）':''}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}
function select(name,label,options,value){return `<label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select>`}
function area(name,label,value=''){return `<label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea>`}
let scheduleEndEdited=false;
function scheduleYearLater(date){const d=new Date(date+'T12:00:00');const month=d.getMonth();d.setFullYear(d.getFullYear()+1);if(d.getMonth()!==month)d.setDate(0);return dayKey(d)}
function openForm(type='task',record=null){if(type==='review'){page='review';reviewDate=today;reviewSelected=null;$('#dialog').close();render();return}if(type==='note'&&!state.learningCategories.length){toast('请先新增一个学习分类');type='category'}if(type==='schedule'&&record?.dates){toast('此历史安排按指定日期执行，暂不支持用每周编辑器修改；可以删除后手动新建');return}$('#dialog-notice')?.remove();formType=type;editing=record?.id||null;scheduleEndEdited=false;const r=record||{};$('#dialog-title').textContent={habitBackfill:'补打卡',progress:'记录进展',progressDelete:'删除进展',categories:'管理学习分类',category:editing?'重命名分类':'新增分类',deleteCategory:'删除分类',period:'记录经期',periodDay:'每日情况',removeRecurring:'删除重复安排',deleteTask:'删除任务',task:editing?'编辑任务':'记录一件事',note:'学习记录',money:'记一笔',workout:editing?'编辑运动记录':'运动记录',idea:'记下灵感',goal:'编辑个人规划',planningLinks:'关联已有行动',planningManage:'管理规划',review:'今日复盘',schedule:editing?'编辑固定安排系列':'新增固定安排',habitdef:'新增习惯',folder:editing?'重命名文件夹':'新建文件夹',workoutTypes:'管理运动类型',profile:'编辑个人资料'}[type];let content='';if(type==='workoutTypes')content=workoutTypesManager();if(type==='habitBackfill')content='<p>'+esc(r.name)+'</p>'+field('date','补打卡日期','date',today,'required min="'+esc(r.startDate||'')+'" max="'+today+'"')+'<p class="muted">选择实际完成的日期。补打卡只记录习惯完成，不会新增运动时长或复盘内容。</p>';if(type==='progress'||type==='progressDelete')content='<input type="hidden" name="goalId" value="'+esc(r.goalId)+'">'+(type==='progressDelete'?'<p>确定删除 '+esc(r.date)+' 的这条进展记录？</p>':field('date','日期','date',r.date||today,'required')+'<label for="f-content">进展内容（必填）</label><textarea id="f-content" name="content" required maxlength="20000" rows="7" placeholder="写下进展，有下一步想法也可以一起写">'+esc(r.content||'')+'</textarea>');if(type==='categories')content=categoryManager();if(type==='category')content=field('name','分类名称','text',r.name||'','required maxlength="20"');if(type==='deleteCategory')content='<p>删除「'+esc(r.name)+'」分类。</p>'+((state.notes.some(n=>n.group===r.name)||state.folders.some(f=>f.group===r.name))?select('destination','将文件夹和记录移至',state.learningCategories.filter(n=>n!==r.name),'')+'<p class="muted">保留原文件夹、记录、链接和附件。</p>':'<p>该分类没有内容，可以直接删除。</p>');if(type==='period'||type==='periodDay')content=periodForm(type,r);if(type==='deleteTask')content='<p>确定删除「'+esc(r.title)+'」？任务和时间安排中的这条记录会移除，相关灵感会保留。</p>';if(type==='removeRecurring')content=r.startDate>r.endDate?'<p>此安排的结束日期早于开始日期，已无法正常执行。确认移除这条异常安排？已有任务、打卡和专注记录会保留。</p>':'<p>选择删除范围，过去记录会保留。</p>'+(r.seriesId?select('scope','删除范围',['仅这一次','这次及以后'],'仅这一次'):field('effectiveDate','从哪一天起删除','date',r.startDate>today?r.startDate:today,'required min="'+today+'"')) ;if(type==='task')content=select('recordType','记录类型',['任务','学习记录','收支','运动','灵感','复盘'],'任务')+field('title','任务名称','text',r.title,'required maxlength="160"')+taskGroupFields(r)+field('date','计划日期','date',r.date||selectedDate,'required')+field('time','安排时间（可选）','time',r.time)+field('duration','预计分钟','number',r.duration||30,'min="1" max="1440" required');if(type==='note')content=field('title','标题','text',r.title,'required maxlength="160"')+select('group','所属分类',state.learningCategories,r.group||(state.learningCategories.includes(filter)?filter:state.learningCategories[0]))+folderSelect(r)+area('content','记录',r.content)+field('minutes','实际学习分钟','number',r.minutes||0,'min="0" max="1440" required')+noteLinksEditor(Array.isArray(r.links)?r.links:[])+attachmentEditor(r);if(type==='money')content=moneyForm(r);if(type==='workout')content=workoutTypeFields(r)+field('minutes','运动分钟','number',r.minutes||30,'required min="1" max="1440"')+field('calories','燃烧热量（千卡，可选）','number',r.calories??'','min="0" max="100000" step="1"')+field('date','日期','date',r.date||today,'required')+area('details','详情（可选）',r.details)+'<p class="muted">可以写训练动作、组数和重量，新运动的学习进度，或这次运动的身体感受。</p>'+'<p class="muted">今日累计达到 30 分钟，将同步完成运动习惯。</p>';if(type==='idea')content=field('title','一个想法','text','','required maxlength="160"')+area('content','多写几句（可选）')+select('tag','分类',['随手记','科研灵感','生活随想','值得探索'],'随手记');if(type==='goal')content=field('title','规划名称','text',r.title,'required maxlength="160"')+select('horizon','规划类型',['短期','长期'],planningType(r))+select('status','状态',['进行中','已完成','已归档'],r.status||'进行中')+field('startDate','开始日期（可选）','date',r.startDate)+field('endDate','结束日期（可选）','date',r.endDate)+area('content','规划内容（可选）',r.content)+'<p class="muted">可以写背景、想达到的结果、行动思路和阶段安排。</p><label>所属长期规划（短期规划可选）</label><select name="parentId"><option value="">不关联</option>'+state.goals.filter(g=>g.id!==r.id&&planningType(g)==='长期'&&!g.parentId).map(g=>`<option value="${esc(g.id)}" ${g.id===r.parentId?'selected':''}>${esc(g.title)}</option>`).join('')+'</select>';if(type==='planningLinks')content=planningLinks(r);if(type==='planningManage')content=select('operation','操作',['归档','删除'],'归档')+'<p class="muted">删除规划会解除关联，任务、固定安排和习惯记录都保留。</p>';if(type==='review')content=field('title','标题','text','今天的小结','required maxlength="160"')+area('content','收获、阻碍与明天的调整','今天的收获：\n\n想调整的事：\n\n明天的一小步：')+field('date','日期','date',today,'required');if(type==='schedule')content=field('title','名称（课程、组会等）','text',r.title,'required maxlength="160"')+field('startTime','开始时间','time',r.startTime||'08:00','required')+field('endTime','结束时间','time',r.endTime||'09:30','required')+'<fieldset class="weekday-fields"><legend>每周重复</legend>'+[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="weekdays" value="${d}" ${(r.weekdays||[String(new Date(selectedDate+'T12:00:00').getDay())]).includes(String(d))?'checked':''}>周${['日','一','二','三','四','五','六'][d]}</label>`).join('')+'</fieldset>'+field('startDate','开始日期','date',r.startDate||selectedDate,'required')+field('endDate','结束日期','date',r.endDate||scheduleYearLater(r.startDate||selectedDate),'required')+field('place','地点（可选）','text',r.place,'maxlength="100"')+'<p class="muted">固定安排按所选时间与星期显示。</p>';if(type==='habitdef')content=field('name','习惯名称','text','','required maxlength="40"')+field('startDate','开始日期','date',today,'required')+'<p class="muted">每天一次，可在月历中补录开始日期以后的打卡。</p>';if(type==='folder')content=field('name','文件夹名称','text',r.name||'','required maxlength="40" placeholder="例如：研一上、2026"')+'<input type="hidden" name="group" value="'+esc(r.group)+'"><p class="muted">所属分类：'+esc(r.group)+'</p><p id="folder-error" role="alert"></p>';if(type==='profile')content=field('name','工作台名称','text',state.name,'required maxlength="12"')+field('user','昵称','text',state.user,'required maxlength="20"')+field('avatar','头像（可选，图片不超过 2MB）','file','','accept="image/png,image/jpeg,image/webp"')+workspaceLogoEditor();if(type==='schedule')content+='<label class="task-priority-option"><input type="checkbox" name="addToTasks" '+(scheduleAddsTasks(r)?'checked':'')+'> 同时添加到当天任务</label><p class="muted">可选。勾选后，在所选日期范围内按重复星期添加待办，时间与固定安排一致，可独立打卡和计时。</p>';if(type==='schedule'&&editing)content+=field('effectiveDate','修改从哪一天生效','date',r.startDate>today?r.startDate:today,'required min="'+today+'"')+'<p class="muted">修改影响此日及以后，过去记录保留。</p>';if(type==='task'&&!r.seriesId)content+=scheduleTaskPicker(r);if(['task','schedule','habitdef'].includes(type))content+=planningPicker(r.goalId||'');if(type==='task'||type==='schedule')content+=area('description','描述（可选）',r.description);if(type==='task'&&r.seriesId)content+=select('editScope','修改范围',['仅这一次','这次及以后'],'仅这一次');if(type==='task')content+='<label class="task-priority-option"><input type="checkbox" name="priority" '+(r.priority?'checked':'')+'> 设为当天重点（最多 3 项）</label>';if(type==='task'&&editing)content+='<button type="button" data-remove-task="'+esc(editing)+'">删除任务</button>';$('#form button[type="submit"]').hidden=type==='categories';$('#form button[type="submit"]').textContent=['deleteTask','removeRecurring','deleteCategory','progressDelete'].includes(type)?'确认删除':'保存';$('#fields').innerHTML=content;if(type==='note')renderAttachmentDraft();$('#form').noValidate=true;decorateLunarDates();$('#dialog').showModal();if(type==='folder')$('#f-name')?.focus()}
document.addEventListener('change',e=>{if(e.target.name==='recordType'){let type={'任务':'task','学习记录':'note','收支':'money','运动':'workout','灵感':'idea','复盘':'review'}[e.target.value];$('#dialog').close();openForm(type)}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.workoutMode){workoutMode=d.workoutMode;render()}if(d.workoutPeriod){if(d.workoutPeriod==='0')workoutDate=today;else{const dt=new Date(workoutDate+'T12:00:00');if(workoutMode==='month'){dt.setDate(1);dt.setMonth(dt.getMonth()+Number(d.workoutPeriod))}else dt.setDate(dt.getDate()+7*Number(d.workoutPeriod));workoutDate=dayKey(dt)}render()}if(d.financeMode){financeMode=d.financeMode;render()}if(d.financePeriod){if(d.financePeriod==='0')financeDate=today;else{const date=new Date(financeDate+'T12:00:00');if(financeMode==='week')date.setDate(date.getDate()+7*Number(d.financePeriod));else{date.setDate(1);if(financeMode==='year')date.setFullYear(date.getFullYear()+Number(d.financePeriod));else date.setMonth(date.getMonth()+Number(d.financePeriod))}financeDate=dayKey(date)}render()}if('addLink'in d){$('#note-link-rows').insertAdjacentHTML('beforeend',noteLinkRow());$('#note-link-rows').lastElementChild.querySelector('input').focus()}if('removeLink'in d)b.closest('.note-link-row').remove();if(d.planMode){planMode=d.planMode;render()}if(d.period){if(d.period==='0')selectedDate=today;else{const dt=new Date(selectedDate+'T12:00:00');if(planMode==='month'){dt.setDate(1);dt.setMonth(dt.getMonth()+Number(d.period))}else dt.setDate(dt.getDate()+7*Number(d.period));selectedDate=dayKey(dt)}render()}if(d.editSchedule)openForm('schedule',state.schedules.find(r=>r.id===d.editSchedule));if(d.palette&&palettes[d.palette]){state.theme=d.palette;const ok=await save();render();if(ok)toast('主题颜色已保存')}if(d.page){page=d.page;filter='全部';render();window.scrollTo(0,0)}if(d.filter){filter=d.filter;learningFolder=null;render()}if(d.date){selectedDate=d.date;render()}if(d.shift){if(d.shift==='0')selectedDate=today;else{let dt=new Date(selectedDate+'T12:00:00');dt.setDate(dt.getDate()+Number(d.shift));selectedDate=dayKey(dt)}render()}if(d.task){let t=state.tasks.find(t=>t.id===d.task);t.done=!t.done;if(t.done)pauseFocus(t);if(!(await save())){render();return};render()}if(d.removeTask){const t=state.tasks.find(t=>t.id===d.removeTask);openForm(t?.seriesId?'removeRecurring':'deleteTask',t)}if(d.removeSeries)openForm('removeRecurring',state.schedules.find(r=>r.id===d.removeSeries));if(d.editTask)openForm('task',state.tasks.find(t=>t.id===d.editTask));if(d.editWorkout)openForm('workout',state.workouts.find(w=>w.id===d.editWorkout));if(d.editNote)openForm('note',state.notes.find(t=>t.id===d.editNote));if(d.editGoal)openForm('goal',state.goals.find(t=>t.id===d.editGoal));if(d.habit){let k=today+':'+d.habit;if(habitDone(d.habit)&&!state.habits[k]){toast('此打卡来自关联记录，可修改或删除源记录撤销');return}state.habits[k]=!state.habits[k];if(!(await save())){render();return};render()}if(d.convert){let n=state.ideas.find(i=>i.id===d.convert);if(!n.taskId){n.taskId=id();state.tasks.push({id:n.taskId,title:n.title,group:'生活事务',date:today,time:'',duration:30,done:false,ideaId:n.id});if(!(await save())){render();return};render();toast('已加入今日任务，保留灵感关联')}}if(d.delete){let [key,rec]=d.delete.split(':');if(confirm('删除这条记录？相关统计将同步更新。')){const prior=state[key];state[key]=state[key].filter(x=>x.id!==rec);if(!(await save())){state[key]=prior;render();return};render();toast('记录已删除')}}if(d.action){if(d.action==='close')$('#dialog').close();else if(d.action==='theme'){state.dark=!state.dark;if(!(await save())){render();return};render()}else if(d.action==='export'){const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download='有序-本机备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}else if(d.action==='planningLinks')openForm('planningLinks',state.goals.find(g=>g.id===d.planningId));else if(d.action==='workoutTypes'){$('#dialog').close();openForm('workoutTypes')}else openForm(d.action==='new'?'task':d.action)}});
$('#form').addEventListener('submit',async e=>{e.preventDefault();try{$('#dialog-notice')?.remove();if(formType==='scheduleTasks')return;if(!validateWorkspaceForm(e.target))return;const values=Object.fromEntries(new FormData(e.target));let priorWorkoutTypes;for(const k in values)if(typeof values[k]==='string')values[k]=values[k].trim();if(formType==='habitBackfill'){await saveHabitBackfill(values);return}if(formType==='progress'||formType==='progressDelete'){await saveProgress(values);return}if(['goal','planningLinks','planningManage'].includes(formType)){await savePlanning(values,e.target);return}if(formType==='money'){await saveMoney(values);return}if(formType==='category'||formType==='deleteCategory'){await saveCategory(values);return}if('title'in values&&!values.title){toast('请填写标题');return}if(formType==='task'){if(values.group==='其他'){const custom=values.customGroup?.trim();if(!custom||custom.length>20||custom==='其他'){showFieldError($('#form'),'customGroup','请填写具体类别名称（1–20字）');return}values.group=custom}delete values.customGroup;if('scheduleLinkId' in values){const r=scheduleChoices().find(([key])=>key===values.scheduleLinkId)?.[1];values.scheduleLinkName=values.scheduleLinkId?(r?.title||state.tasks.find(t=>t.id===editing)?.scheduleLinkName||'固定安排'):''}values.priority=values.priority==='on';if(values.priority&&state.tasks.filter(t=>t.id!==editing&&t.date===values.date&&t.priority).length>=3){toast('这一天已有 3 项重点，请先取消一项');return}}if(formType==='period'||formType==='periodDay'){await savePeriodForm(values);return}if(formType==='workout'){priorWorkoutTypes=state.workoutTypes.slice();if(values.title==='其他'){if(!values.customTitle){toast('请填写运动名称');return}values.title=values.customTitle;if(!defaultWorkoutTypes.includes(values.title)&&!state.workoutTypes.includes(values.title))state.workoutTypes.push(values.title)}delete values.customTitle;values.calories=values.calories===''?null:Number(values.calories);if(values.calories!==null&&(!Number.isFinite(values.calories)||values.calories<0)){toast('请填写有效热量');return}}if(formType==='removeRecurring'){await removeRecurring(values);return}if(formType==='deleteTask'){const priorTasks=state.tasks,priorIdeas=state.ideas;state.tasks=state.tasks.filter(t=>t.id!==editing);state.ideas=state.ideas.map(i=>i.taskId===editing?{...i,taskId:null}:i);if(!(await save())){state.tasks=priorTasks;state.ideas=priorIdeas;toast('删除未保存，请重试');return}$('#dialog').close();render();toast('任务已删除');return}if(formType==='note'){values.links=[];for(const row of document.querySelectorAll('.note-link-row')){const name=row.querySelector('[data-link-name]').value.trim(),raw=row.querySelector('[data-link-url]').value.trim();if(!name&&!raw)continue;const url=validNoteURL(raw);if(!url){const message='请填写完整的 http:// 或 https:// 网页链接';$('#note-link-error').textContent=message;$('.note-links-editor').open=true;row.querySelector('[data-link-url]').focus();return}values.links.push({name:name||new URL(url).hostname,url})}}if(formType==='note'){if(values.folderId&&!state.folders.some(f=>f.id===values.folderId&&f.group===values.group)){toast('请选择该分类下的有效文件夹');return}await saveNoteWithAttachments(values);return}if(formType==='schedule'){values.addToTasks=values.addToTasks==='on';values.weekdays=new FormData(e.target).getAll('weekdays');if(!values.weekdays.length){showFieldError($('#form'),'weekdays','请至少选择一个重复星期');return}if(values.startDate>values.endDate||values.effectiveDate>values.endDate){showFieldError($('#form'),'endDate','结束日期不能早于开始或生效日期');return}if(values.startTime>=values.endTime){showFieldError($('#form'),'endTime','结束时间必须晚于开始时间');return}await saveRecurringSchedule(values);return}if(formType==='folder'){const name=values.name,group=values.group;const error=$('#folder-error');if(!state.learningCategories.includes(group)||!name||name.length>40){error.textContent='请填写 1–40 个字的文件夹名称';return}if(name==='未分类'||state.folders.some(f=>f.group===group&&f.name===name&&f.id!==editing)){error.textContent='该分类中已有同名文件夹，请换一个名称';return}const prior=structuredClone(state.folders);const existing=state.folders.find(f=>f.id===editing);const recordId=existing?.id||id();if(existing)existing.name=name;else state.folders.push({id:recordId,name,group});const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{if(!(await save())){state.folders=prior;error.textContent='文件夹未保存，请查看保存提示后重试';return}filter=group;learningFolder=null;$('#dialog').close();render();toast(existing?'文件夹已重命名':'文件夹已创建')}finally{submit.disabled=false}return}if(formType==='habitdef'){if(!values.name||values.startDate>today){toast('请填写习惯名称，开始日期不能晚于今天');return}if(state.habitDefinitions.some(h=>h.name===values.name)){toast('已有同名习惯');return}const previous=state.habitDefinitions;const h={id:id(),name:values.name,startDate:values.startDate,goalId:values.goalId||''};state.habitDefinitions=[...previous,h];if(!(await save())){state.habitDefinitions=previous;return}habitSelected=h.id;$('#dialog').close();render();return}if(formType==='task'&&values.editScope==='这次及以后'){const task=state.tasks.find(t=>t.id===editing),series=state.schedules.find(r=>r.id===task?.seriesId);if(!series)return;if(values.date!==task.date){showFieldError($('#form'),'date','修改此日及以后时请保留原日期');return}const end=minutes(values.time||series.startTime)+Number(values.duration);if(end>=1440){showFieldError($('#form'),'duration','时间范围不能跨过午夜');return}editing=series.id;await saveRecurringSchedule({...series,goalId:values.goalId||'',title:values.title,description:values.description,group:values.group,startTime:values.time||series.startTime,endTime:String(Math.floor(end/60)).padStart(2,'0')+':'+String(end%60).padStart(2,'0'),effectiveDate:task.date});return}delete values.editScope;if(formType==='profile'){if(!values.name||!values.user){toast('请填写名称和昵称');return}let avatar=state.avatar,file=values.avatar;if(file?.size){if(file.size>2097152||!['image/png','image/jpeg','image/webp'].includes(file.type)){toast('请选择 2MB 以内的 PNG、JPG 或 WebP 图片');return}try{avatar=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)})}catch{toast('图片读取失败');return}}let workspaceImage=values.removeWorkspaceImage?'':state.workspaceImage||'';try{if(values.workspaceFile?.size)workspaceImage=await readWorkspaceImage(values.workspaceFile)}catch(error){toast(error.message);return}Object.assign(state,{name:values.name,user:values.user,avatar,workspaceImage,workspaceSymbol:values.workspaceSymbol||'wave'})}else{let key={schedule:'schedules',task:'tasks',note:'notes',money:'money',workout:'workouts',idea:'ideas',goal:'goals',review:'reviews'}[formType];delete values.recordType;['minutes','amount','duration','progress','distance'].forEach(k=>{if(k in values)values[k]=Number(values[k])});if(formType==='money')values.amount=Math.round(values.amount*100)/100;if(formType==='note')values.date=today;if(editing)Object.assign(state[key].find(x=>x.id===editing),values);else{const entry={id:id(),...values,...(formType==='task'?{done:false}:{})};state[key].unshift(entry);editing=entry.id}}const ok=await save();if(!ok&&formType==='workout'&&typeof priorWorkoutTypes!=='undefined')state.workoutTypes.splice(0,state.workoutTypes.length,...priorWorkoutTypes);if(ok)$('#dialog').close();render();if(ok)toast(window.gradlifeCloud?'已保存到云端':'已保存到当前浏览器')}catch(error){console.error('表单保存失败',error);toast('保存未完成，请检查填写内容后重试；若仍失败，请告知所在页面。')}});
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_today_tasks',description:'读取当前工作台今天的任务，不修改数据。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('此工具不接受参数');return {date:today,tasks:tasksFor(today).map(({id,title,done,time})=>({id,title,done,time}))}}})).catch(()=>{})}catch{}}

document.addEventListener('change',e=>{if(formType==='note'&&e.target.name==='group')$('#f-folderId').innerHTML=folderOptions(e.target.value)});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.openFolder){filter=d.folderGroup;learningFolder=d.openFolder;render()}if('folderBack'in d){learningFolder=null;render()}if(d.newFolder||d.renameFolder){const existing=state.folders.find(f=>f.id===d.renameFolder);openForm('folder',existing||{group:d.newFolder});}if(d.removeFolder){const f=state.folders.find(f=>f.id===d.removeFolder);if(!f||!confirm('删除“'+f.name+'”？其中记录会移回未分类，链接和附件保留。'))return;const oldFolders=state.folders,oldNotes=state.notes;state.folders=state.folders.filter(x=>x.id!==f.id);state.notes=state.notes.map(n=>n.folderId===f.id?{...n,folderId:''}:n);if(!(await save())){state.folders=oldFolders;state.notes=oldNotes}learningFolder=null;render()}});

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.habitStats){habitSelected=d.habitStats;render()}if(d.habitMode){habitMode=d.habitMode;render()}if(d.habitPeriod){const dt=new Date(habitDate+'T12:00:00');dt.setDate(1);if(d.habitPeriod==='0')habitDate=today;else{if(habitMode==='year')dt.setFullYear(dt.getFullYear()+Number(d.habitPeriod));else dt.setMonth(dt.getMonth()+Number(d.habitPeriod));habitDate=dayKey(dt)}render()}if(d.habitMonth){habitDate=habitDate.slice(0,4)+'-'+String(d.habitMonth).padStart(2,'0')+'-01';habitMode='month';render()}if(d.habitDay){const h=state.habitDefinitions.find(h=>h.id===habitSelected),date=d.habitDay;if(!h||date>today||date<h.startDate)return;const key=date+':'+h.id;if(habitDone(h.id,date)&&!state.habits[key]){toast('此打卡由源记录自动完成，请修改对应运动或复盘');return}const previous=state.habits[key];state.habits[key]=!previous;if(!(await save()))state.habits[key]=previous;render()}if(d.habitDelete){const h=state.habitDefinitions.find(h=>h.id===d.habitDelete);if(!h||!confirm('删除“'+h.name+'”及其手动打卡历史？运动和复盘原始记录不会删除。'))return;const old=state.habitDefinitions,logs=state.habits;state.habitDefinitions=old.filter(x=>x.id!==h.id);state.habits=Object.fromEntries(Object.entries(logs).filter(([k])=>!k.endsWith(':'+h.id)));if(!(await save())){state.habitDefinitions=old;state.habits=logs}render()}});

document.addEventListener('change',e=>{if(e.target.id==='habit-stats-selector'&&state.habitDefinitions.some(h=>h.id===e.target.value)){habitSelected=e.target.value;render();$('#habit-stats-selector')?.focus()}});

document.addEventListener('change',e=>{if(formType==='workout'&&e.target.name==='title'){const custom=e.target.value==='其他';$('#custom-workout').hidden=!custom;$('#f-customTitle').disabled=!custom;$('#f-customTitle').required=custom;if(custom)$('#f-customTitle').focus()}});

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if('newToday'in d)openForm('task',{date:today});if(d.priorityTask){const task=state.tasks.find(t=>t.id===d.priorityTask);if(!task)return;if(!task.priority&&state.tasks.filter(t=>t.date===task.date&&t.priority).length>=3){toast('这一天已有 3 项重点，请先取消一项');return}const prior=!!task.priority;task.priority=!prior;b.disabled=true;try{if(!(await save())){task.priority=prior;toast('重点未保存，请重试')}render()}finally{b.disabled=false}}});

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.openFocus){if(page!=='focus')focusReturnPage=page;focusTaskId=d.openFocus;page='focus';render()}if('focusBack'in d){page=focusReturnPage;render()}if(d.endFocus&&!focusBusy){const t=state.tasks.find(t=>t.id===d.endFocus);if(!t)return;focusBusy=true;const prior={focusMs:t.focusMs,focusStartedAt:t.focusStartedAt,focusSessionBase:t.focusSessionBase};pauseFocus(t);t.focusSessionBase=t.focusMs||0;render();try{if(await save()){page=focusReturnPage;toast('本次专注已保存')}else{Object.assign(t,prior);toast('未保存，请重试')}}finally{focusBusy=false;render()}}});
setInterval(()=>{document.querySelectorAll('[data-focus-session]').forEach(el=>{const t=state.tasks.find(t=>t.id===el.dataset.focusSession);if(t)el.textContent=focusTime(Math.max(0,focusElapsed(t)-(t.focusSessionBase||0)))})},1000);

function focusTotalText(ms){const minutes=Math.floor(ms/60000);return ms>0&&minutes===0?'不足 1 分钟':minutes>=60?Math.floor(minutes/60)+' 小时 '+minutes%60+' 分钟':minutes+' 分钟'}
setInterval(()=>{document.querySelectorAll('[data-focus-total]').forEach(el=>{const t=state.tasks.find(t=>t.id===el.dataset.focusTotal);if(t)el.textContent=focusTotalText(focusElapsed(t))})},1000);

document.addEventListener('change',e=>{if(formType!=='schedule')return;if(e.target.name==='endDate')scheduleEndEdited=true;if(e.target.name==='startDate'&&!editing&&!scheduleEndEdited&&e.target.value)$('#f-endDate').value=scheduleYearLater(e.target.value)});
function showFieldError(form,name,message,focus=true){const input=Array.from(form.elements).find(el=>el.name===name);if(!input)return;input.setAttribute('aria-invalid','true');const error=document.createElement('p');error.className='field-error';error.dataset.fieldError=name;error.textContent=message;error.id='error-'+input.id;error.setAttribute('role','alert');input.setAttribute('aria-describedby',error.id);(input.closest('fieldset')||input).insertAdjacentElement('afterend',error);if(focus){input.scrollIntoView({block:'center',behavior:'smooth'});input.focus()}}
function validateWorkspaceForm(form){form.querySelectorAll('.field-error').forEach(el=>el.remove());form.querySelectorAll('[aria-invalid]').forEach(el=>{el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby')});let first=null;for(const input of form.elements){if(input.disabled||!['INPUT','TEXTAREA','SELECT'].includes(input.tagName))continue;const label=(input.labels?.[0]?.textContent||input.name||'此项').replace('（必填）','').trim();let message='';if(input.required&&(!input.value.trim()||(input.type==='checkbox'&&!input.checked)))message='请填写'+label;else if(!input.validity.valid)message=input.validity.rangeUnderflow?label+'不能小于 '+input.min:input.validity.rangeOverflow?label+'不能大于 '+input.max:input.validity.stepMismatch?'请按规定格式填写'+label:'请正确填写'+label;if(message){showFieldError(form,input.name,message,false);if(!first)first=input}}if(first){first.scrollIntoView({block:'center',behavior:'smooth'});first.focus();return false}return true}
document.addEventListener('input',e=>{const form=e.target.form;if(!form)return;const name=e.target.name;form.querySelectorAll('.field-error').forEach(el=>{if(el.dataset.fieldError===name)el.remove()});e.target.removeAttribute('aria-invalid');e.target.removeAttribute('aria-describedby')});
function categoryManager(){return state.learningCategories.map((name,i)=>`<div class="record-row"><span class="grow">${esc(name)}</span><button type="button" data-rename-category="${i}">重命名</button><button type="button" data-remove-category="${i}">删除</button></div>`).join('')+'<button type="button" data-action="category">＋ 新增分类</button>'}
async function saveCategory(values){const old=editing,remove=formType==='deleteCategory',name=values.name;const hasContent=state.notes.some(n=>n.group===old)||state.folders.some(f=>f.group===old);if(remove){if(hasContent&&(!values.destination||values.destination===old||!state.learningCategories.includes(values.destination))){toast('请先新增另一个分类，用于接收现有内容');return}}else if(!name||name.length>20||name==='全部'||state.learningCategories.some(n=>n===name&&n!==old)){showFieldError($('#form'),'name','请输入不重复的分类名称（1–20字，不能为全部）');return}const before=structuredClone({learningCategories:state.learningCategories,notes:state.notes,folders:state.folders});if(remove)state.learningCategories=state.learningCategories.filter(n=>n!==old);else if(old)state.learningCategories=state.learningCategories.map(n=>n===old?name:n);else state.learningCategories.push(name);if(old){const dest=remove?values.destination:name;state.notes=state.notes.map(n=>n.group===old?{...n,group:dest}:n);state.folders=state.folders.map(f=>f.group===old?{...f,group:dest}:f)}if(!(await save())){Object.assign(state,before);toast('分类未保存，请重试');return}filter='全部';learningFolder=null;$('#dialog').close();render();toast('分类已更新')}
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if('renameCategory'in d){const name=state.learningCategories[Number(d.renameCategory)];openForm('category',{id:name,name})}if('removeCategory'in d){const name=state.learningCategories[Number(d.removeCategory)];openForm('deleteCategory',{id:name,name})}});
